@startuml

class H2SLocation {
  + Name : string
}

class Resident {
  + Name : string
  + StreetAddress : string
  + PhoneNumber : string
  + Email : string
}

class ScheduledPickup {
  + StreetAddress : string
  + Description : string
  + PickupTime : time
}

class Vehicle {
  + StorageSpace : float
}

class VolunteerDriver {
  + AvailableDays : string[]
}

class PickupRoute {
  + Date : date
}

class Item {
  + Description : string
  + Dimensions : string
  + Weight : float
}

class Category {
  + Name : string
}

class Article {
  + RFID : string
  + Description : string
}

class Client {
  + HomeAddress : string
  + NeededCategories : Category[]
}

class H2SEmployee {
  + Name : string
}

class FoodBank {
  + Name : string
}

H2SLocation "1" -- "*" Resident
H2SLocation "1" -- "*" Vehicle
H2SLocation "1" -- "*" H2SEmployee
H2SLocation "1" -- "*" VolunteerDriver
H2SLocation "1" -- "0..1" FoodBank

Resident "1" -- "*" ScheduledPickup
ScheduledPickup "1" -- "1" Vehicle
ScheduledPickup "1" -- "1..*" Item
Vehicle "1" -- "*" PickupRoute
PickupRoute "1" -- "1" VolunteerDriver
PickupRoute "1" -- "*" ScheduledPickup

Item "1" -- "0..1" Article
Article "1" -- "1" Category
Article "1" -- "1" H2SEmployee : examined by
Article "1" -- "1" H2SEmployee : assigned category

Client "1" -- "*" Article : receives
H2SEmployee "1" -- "*" Client : calls
VolunteerDriver "1" -- "*" Article : delivers

@enduml

